using System;using System.IO;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
/* Column Schedule Formatter: the new template is written, read back unchanged, and gives the bars of the Bar Bending Schedule */
class ColumnScheduleTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}
 static ColumnCell Cell(int corner,int side){var c=new ColumnCell{B=500,H=500,TieDia=10,S1Main=75,S1Other=75,S2=200,Lo=585,Cover=40,Concrete="C35",Fy=414};
  foreach(var p in new[]{new[]{60.0,60},new[]{440.0,60},new[]{60.0,440},new[]{440.0,440}})c.Bars.Add(new ColumnBar{X=p[0],Y=p[1],Dia=corner});foreach(var p in new[]{new[]{187.0,60},new[]{313.0,60},new[]{187.0,440},new[]{313.0,440},new[]{60.0,187},new[]{60.0,313},new[]{440.0,187},new[]{440.0,313}})c.Bars.Add(new ColumnBar{X=p[0],Y=p[1],Dia=side});
  c.Links.Add(new ColumnLink{X0=40,Y0=40,X1=460,Y1=460});c.Links.Add(new ColumnLink{X0=167,Y0=40,X1=333,Y1=460});c.Links.Add(new ColumnLink{X0=250,Y0=60,X1=250,Y1=440});return c;}
 static void Main(){var s=new ColumnSchedule();s.Levels.Add(new ColumnLevel{FromM=0.6,ToM=4.6});s.Levels.Add(new ColumnLevel{FromM=4.6,ToM=8.6});foreach(var m in new[]{"C1","C2","C3"})s.Marks.Add(m);
  for(int l=0;l<2;l++){s.Cells[ColumnSchedule.Key("C1",l)]=Cell(20,16);s.Cells[ColumnSchedule.Key("C2",l)]=Cell(20,16);s.Cells[ColumnSchedule.Key("C3",l)]=Cell(25,20);}
  var groups=ColumnFormatter.Group(s,"C",true);Check(groups.Count==2&&groups[0].Originals=="C1, C2"&&groups[0].Mark=="C1","identical columns are grouped under new marks");
  var sheet=ColumnFormatter.Layout(s,groups,"TEST");Check(sheet.Items.Any(i=>i.Kind=="TEXT"&&i.Text=="SCHEDULE OF COLUMNS")&&sheet.Items.Any(i=>i.Kind=="TEXT"&&i.Text=="COLUMN MARKED"),"owner template: title and COLUMN MARKED");Check(sheet.Items.Any(i=>i.Kind=="TEXT"&&i.Layer=="CELLTEXT"&&i.Text.Contains("LATERAL TIES SPACED AT")&&i.Text.Contains("(3 TIES/SET)")),"cell text as the owner template");Check(sheet.Items.Any(i=>i.Kind=="RRECT"&&i.Layer=="MAINLINK")&&sheet.Items.Any(i=>i.Kind=="TEXT"&&i.Layer=="LEGEND"&&i.Text=="%%C20mm"),"main link drawn apart, bar legend under REMARKS");Check(sheet.Items.Count(i=>i.Kind=="RECT"&&i.Layer=="CELLBOX")==2,"the same section at both levels is one wide cell");
  string path=Path.Combine(Path.GetTempPath(),"ColumnScheduleTest-"+Guid.NewGuid().ToString("N")+".dxf");ColumnFormatter.ToDxf(sheet,s,groups).Write(path);
  try{var back=ColumnScheduleReader.Read(File.ReadAllText(path));Check(back.Marks.SequenceEqual(new[]{"C1","C2"}),"marks read back");Check(back.Levels.Count==2,"levels read back");
   for(int l=0;l<2;l++){int lb=back.Levels.FindIndex(q=>Math.Abs(q.FromM-s.Levels[l].FromM)<1e-9);Check(lb>=0,"level found");Check(back.Cell("C1",lb).Signature()==s.Cell("C1",l).Signature(),"section, bars, links and ties read back unchanged");Check(back.Cell("C2",lb).MainText==s.Cell("C3",l).MainText,"main bars read back");}
   Check(back.Originals["C1"]=="C1, C2","original marks read back");
   var cfg=CalculationStore.All().First(c=>c.Name.Contains("FC28")&&c.Name.Contains("G40/G60"));var set=new CutSettings{Config=cfg};var pieces=ColumnFormatter.BbsPieces(back,set,new List<string>());
   var hoops=pieces.Where(p=>p.Line=="Column C1"&&p.Location.StartsWith("Column hoops")).ToList();Check(hoops.Count==2&&hoops.All(p=>p.PerLine==30&&p.Lines==2),"hoops: 2 x (585 / 75 + 1) in Lo + 14 at 200 in a 4 m level, 2 identical columns");
   Check(pieces.Any(p=>p.Line=="Column C1"&&p.Location.StartsWith("Column crossties")),"crossties");var top=pieces.Where(p=>p.Line=="Column C1"&&p.Location.Contains("8.6 m (top")).ToList();Check(top.Count==2&&top.All(p=>p.Shape=="90° hook one end"),"top level bars are hooked");
   var lower=pieces.First(p=>p.Line=="Column C1"&&p.Diameter==16&&p.Location.Contains("0.6 to 4.6"));Check(Math.Abs(lower.Length-(4+BeamCutting.SpliceLap(set,16,false)))<1e-9,"lower level bars lap into the level above");}
  finally{File.Delete(path);}
  /* open extra ties as the owner's sample: each inner link two C-shaped ties, the option and Lo kept in the hidden data */
  s.OpenExtra=true;var sheet3=ColumnFormatter.Layout(s,groups,"");Check(sheet3.Items.Count(i=>i.Kind=="PLINE"&&i.Layer=="OPENTIES")==2*2,"open ties: two C ties per inner link (one merged cell per mark)");Check(sheet3.Items.Any(i=>i.Kind=="TEXT"&&i.Layer=="CELLTEXT"&&i.Text.Contains("(3 TIES/SET)")&&!i.Text.Contains("Lo =")),"cell text as the sample");
  string path3=Path.Combine(Path.GetTempPath(),"ColumnScheduleOpen-"+Guid.NewGuid().ToString("N")+".dxf");ColumnFormatter.ToDxf(sheet3,s,groups).Write(path3);try{var raw3=File.ReadAllText(path3);var back3=ColumnScheduleReader.Read(raw3);Check(back3.OpenExtra&&back3.Cell("C1",0).Lo==585&&back3.Originals["C1"]=="C1, C2","open ties, Lo and original marks read back");Check(raw3.Contains("DTCE-DATA"),"hidden data layer");}finally{File.Delete(path3);}
  s.OpenExtra=false;
  /* ACI detailing option: # bars, ACI spacing wording, the readers still take the file */
  string beam="1 - 50mm, 15 - 75mm, AND REST AT 125mm C/C";string aci=AciDetailing.Notation(beam,"Beam");Check(aci=="1 @ 50, 15 @ 75, REST @ 125","ACI stirrup wording: "+aci);Check(AciDetailing.ToStandard(aci)==beam,"ACI stirrup wording reads back: "+AciDetailing.ToStandard(aci));
  Check(AciDetailing.Notation("%%C10 @ 175mm C/C","Slab")=="#10 @ 175 O.C.","ACI slab bar wording");Check(SlabBar.Parse("#10 @ 175 O.C.").SpacingMm==175,"slab reader takes O.C.");
  var sheet2=ColumnFormatter.Layout(s,groups,"TEST",true);AciDetailing.Apply(sheet2);Check(sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Text=="COLUMN SCHEDULE")&&sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Text=="TIE ARRANGEMENT")&&sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Text=="TIES / HOOPS"),"ACI column schedule as MNL-66 COL-1 / COL-20");Check(sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Layer=="TIES"&&i.Text.StartsWith("#10 @ 75"))&&sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Layer=="MAIN"&&i.Text=="4-#20 + 8-#16"),"ACI bar and tie notation");Check(sheet2.Items.Count(i=>i.Kind=="RECT"&&i.Layer=="P-CONCRETE")==4,"ACI: the tie arrangement in every level cell");Check(sheet2.Items.Any(i=>i.Kind=="TEXT"&&i.Text.Contains("18.7.5.1")),"ACI column notes");
  string path2=Path.Combine(Path.GetTempPath(),"ColumnScheduleAci-"+Guid.NewGuid().ToString("N")+".dxf");ColumnFormatter.ToDxf(sheet2,s,groups).Write(path2);try{var back2=ColumnScheduleReader.Read(File.ReadAllText(path2));Check(back2.Cell("C1",0).Signature()==s.Cell("C1",0).Signature(),"ACI column schedule reads back unchanged");}finally{File.Delete(path2);}
  /* ACI beam schedule: G (added bottom bars at the supports) has its own column and placing diagram; a cantilever gets its diagram
     (owner, 24 November 2026: "lahat ng pwedeng mangyari sa schedule ilagay mo") */
  {Func<string,string,string,string,string,string,string,string,bool,BeamRow> row=(mark,bl,bm,br,tl,tm,tr,sp,cant)=>{var r=new BeamRow{Mark=mark,Leg="2",Diameter="%%C10",Spacing=sp};r.Cells[0].Add("300");r.Cells[1].Add("500");r.Cells[2].AddRange(bl.Split(','));r.Cells[3].AddRange(bm.Split(','));r.Cells[4].AddRange(br.Split(','));r.Cells[5].AddRange(tl.Split(','));r.Cells[6].AddRange(tm.Split(','));r.Cells[7].AddRange(tr.Split(','));r.Cells[11].Add("--");r.Cells[13].Add(cant?"CANTILEVER":"-");r.Numbers.Add(mark);return r;};
   var b2=row("B2","2-%%C16,2-%%C20","2-%%C16","2-%%C16","4-%%C16","2-%%C16","4-%%C16","1 - 50mm, 10 - 100mm, AND REST AT 150mm C/C",false);var v=AciBeamSchedule.Values(b2);
   Check(v.Length==17&&v[10]=="L: 2-#20"&&!v[16].Contains("BOT."),"G column: added bottom bars at the left support, not in the remarks: "+string.Join(" | ",v));
   var b3=row("B3","2-%%C16,2-%%C20","2-%%C16","2-%%C16,2-%%C20","2-%%C16","2-%%C16","2-%%C16","1 - 50mm, 10 - 100mm, AND REST AT 150mm C/C",false);Check(AciBeamSchedule.Values(b3)[10]=="2-#20","G the same at both supports");
   var cb=row("CB1","2-%%C16","2-%%C16","2-%%C16","3-%%C16","3-%%C16","3-%%C16","1 - 50mm, AND REST AT 100mm TO FREE END",true);
   var dxf=AciBeamSchedule.Build(new Result{Rows=new List<BeamRow>{b2,cb}},"TEST");var texts=dxf.ModelEntities().Where(e=>e.Type=="TEXT"||e.Type=="MTEXT").Select(e=>string.Concat(e.P.Where(q=>q.Code==1||q.Code==3).Select(q=>q.Value))).ToList();
   Check(texts.Any(t=>t.Contains("BOTTOM BARS AT THE SUPPORTS, G"))&&texts.Any(t=>t.Contains("PLACING DIAGRAM - CANTILEVER"))&&texts.Any(t=>t.Contains("PLACING DIAGRAM - TYPE 1")),"G and cantilever placing diagrams");
   var plain=AciBeamSchedule.Build(new Result{Rows=new List<BeamRow>{row("B1","3-%%C16","3-%%C16","3-%%C16","3-%%C16","3-%%C16","3-%%C16","1 - 50mm, AND REST AT 150mm C/C",false)}},"TEST").ModelEntities().Where(e=>e.Type=="TEXT"||e.Type=="MTEXT").Select(e=>string.Concat(e.P.Where(q=>q.Code==1||q.Code==3).Select(q=>q.Value))).ToList();
   Check(!plain.Any(t=>t.Contains("SUPPORTS, G")||t.Contains("- CANTILEVER")),"the extra diagrams only when the schedule has them");
   var back=AciBeamSchedule.Read(dxf.ModelEntities(),"t.dxf");Check(back!=null&&back.Source.Count==2&&back.Source[0].Cells[2].Count==2,"the ACI schedule still reads back for the BBS");}
  Console.WriteLine("PASS: "+checks+" column schedule formatter checks");}
}
